using System.Collections.ObjectModel;
using System.Globalization;

namespace IncomingTranslator;

internal sealed record UiLanguageChoice(string Code, string Label)
{
    public override string ToString() => Label;
}

/// <summary>Exact-key interface translations. Never use this on spoken text, names, paths or logs.</summary>
internal static class UiText
{
    private static string _language = "en";
    private static readonly IReadOnlyDictionary<string, string[]> Catalog = BuildCatalog();
    internal static readonly IReadOnlyList<UiLanguageChoice> Choices = Array.AsReadOnly(new[]
    {
        new UiLanguageChoice("en", "English"), new UiLanguageChoice("zh-CN", "简体中文"),
        new UiLanguageChoice("ja", "日本語"), new UiLanguageChoice("ko", "한국어")
    });

    public static event Action? LanguageChanged;

    public static string Language
    {
        get => Volatile.Read(ref _language);
        set
        {
            string canonical = NormalizeLanguage(value);
            if (!string.Equals(Interlocked.Exchange(ref _language, canonical), canonical, StringComparison.Ordinal))
                LanguageChanged?.Invoke();
        }
    }

    internal static string NormalizeLanguage(string? value) => value?.Trim().Replace('_', '-').ToLowerInvariant() switch
    {
        "zh" or "zh-cn" or "zh-hans" or "zh-hans-cn" => "zh-CN",
        "ja" or "ja-jp" or "jp" => "ja",
        "ko" or "ko-kr" or "kr" => "ko",
        _ => "en"
    };

    public static bool Contains(string english) => english is not null && Catalog.ContainsKey(english);

    public static string T(string english)
    {
        ArgumentNullException.ThrowIfNull(english);
        int index = Language switch { "zh-CN" => 0, "ja" => 1, "ko" => 2, _ => -1 };
        return index >= 0 && Catalog.TryGetValue(english, out string[]? translations) ? translations[index] : english;
    }

    public static string Format(string englishFormat, params object?[] args)
    {
        ArgumentNullException.ThrowIfNull(englishFormat);
        ArgumentNullException.ThrowIfNull(args);
        string language = Language;
        CultureInfo culture = CultureInfo.GetCultureInfo(language == "en" ? "en-US" : language);
        int index = language switch { "zh-CN" => 0, "ja" => 1, "ko" => 2, _ => -1 };
        string format = index >= 0 && Catalog.TryGetValue(englishFormat, out string[]? translations) ? translations[index] : englishFormat;
        return string.Format(culture, format, args);
    }

    // Read-only test inspection; arrays are copied so tests cannot mutate the live catalogue.
    internal static IReadOnlyDictionary<string, IReadOnlyList<string>> CatalogForTests() =>
        new ReadOnlyDictionary<string, IReadOnlyList<string>>(Catalog.ToDictionary(pair => pair.Key,
            pair => (IReadOnlyList<string>)Array.AsReadOnly((string[])pair.Value.Clone()), StringComparer.Ordinal));

